  AS r(signature text,definer boolean,mutable_path boolean,service_execute boolean)
 LOOP
  fn:=to_regprocedure(expected.signature);
  SELECT p.prosecdef,n.nspname,NOT EXISTS(SELECT 1 FROM unnest(coalesce(p.proconfig,'{}')) c WHERE c LIKE 'search_path=%') AS mutable_path
   INTO actual FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE p.oid=fn;
  IF fn IS NULL OR actual.nspname IS DISTINCT FROM 'public' OR actual.prosecdef IS DISTINCT FROM expected.definer
    OR actual.mutable_path IS DISTINCT FROM expected.mutable_path THEN RAISE EXCEPTION 'reviewed_function_changed'; END IF;
  service_before:=has_function_privilege('service_role',fn,'EXECUTE');
  IF service_before IS DISTINCT FROM expected.service_execute THEN RAISE EXCEPTION 'reviewed_worker_privileges_changed'; END IF;
  IF expected.mutable_path THEN
   EXECUTE format('ALTER FUNCTION %s SET search_path=pg_catalog,public,extensions,pg_temp',expected.signature);
  END IF;
  IF expected.definer THEN
   EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',expected.signature);
   -- Preserve effective existing server privilege, including a former PUBLIC grant.
   IF service_before AND NOT has_function_privilege('service_role',fn,'EXECUTE') THEN
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',expected.signature);
   END IF;
   IF has_function_privilege('anon',fn,'EXECUTE') OR has_function_privilege('authenticated',fn,'EXECUTE')
    THEN RAISE EXCEPTION 'client_definer_privilege_remains'; END IF;
  END IF;
  IF has_function_privilege('service_role',fn,'EXECUTE') IS DISTINCT FROM service_before
   THEN RAISE EXCEPTION 'worker_privilege_regression'; END IF;
 END LOOP;
END $sc_hardening$;
-- Supports exact actor-scoped run history lookup and covers its composite FK.
CREATE INDEX events_organization_run_order_idx ON core_readonly.events(organization_id,run_id,id);
COMMIT;
